WITH exploded AS (SELECT id, service, host, level, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, value), parsed AS (SELECT id, host, level, value, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 2) != 0 AS INT) AS flag_bit2 FROM exploded WHERE host <> 'h1'), with_windows AS (SELECT *, DENSE_RANK() OVER w_grp AS flag_bit2_dense_rank, COUNT(flag_bit2) OVER (PARTITION BY host) AS host_count_flag_bit2, CUME_DIST() OVER w_hist AS status_code_high_cume_dist FROM parsed WHERE host = 'h3' WINDOW w_grp AS (PARTITION BY host, level ORDER BY flag_bit2), w_hist AS (ORDER BY status_code_high)), enriched AS (SELECT *, ROUND(host_count_flag_bit2 / SUM(host_count_flag_bit2) OVER (PARTITION BY host), 4) AS host_count_flag_bit2_share FROM with_windows), cleaned AS (SELECT id, host, level, value, status_code_high, flag_bit2, flag_bit2_dense_rank, host_count_flag_bit2, status_code_high_cume_dist, host_count_flag_bit2_share, UPPER(host) AS host_upper FROM enriched WHERE level <> 'ERROR') SELECT id, level, value, status_code_high, flag_bit2, flag_bit2_dense_rank, host_count_flag_bit2, status_code_high_cume_dist, host_count_flag_bit2_share FROM cleaned ORDER BY flag_bit2, status_code_high_cume_dist DESC;
